-- Friend groups. Named friend_group because "group" is a reserved word.
CREATE TABLE friend_group (
    id          BIGINT      NOT NULL AUTO_INCREMENT PRIMARY KEY,
    name        VARCHAR(64) NOT NULL,
    -- Shared with friends to join; regenerated by the owner to stop old codes working
    invite_code VARCHAR(16) NOT NULL,
    created_by  BIGINT      NOT NULL,
    created_at  DATETIME(6) NOT NULL,
    CONSTRAINT uq_friend_group_invite UNIQUE (invite_code),
    CONSTRAINT fk_friend_group_creator FOREIGN KEY (created_by) REFERENCES app_user (id)
);

CREATE TABLE group_member (
    group_id  BIGINT      NOT NULL,
    user_id   BIGINT      NOT NULL,
    -- OWNER (exactly one per group) or MEMBER
    role      VARCHAR(16) NOT NULL,
    joined_at DATETIME(6) NOT NULL,
    PRIMARY KEY (group_id, user_id),
    CONSTRAINT fk_group_member_group FOREIGN KEY (group_id) REFERENCES friend_group (id),
    CONSTRAINT fk_group_member_user FOREIGN KEY (user_id) REFERENCES app_user (id)
);
CREATE INDEX idx_group_member_user ON group_member (user_id);

-- The group's shared word list.
CREATE TABLE group_word (
    id       BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    group_id BIGINT       NOT NULL,
    word_id  BIGINT       NOT NULL,
    added_by BIGINT       NOT NULL,
    note     VARCHAR(280),
    added_at DATETIME(6)  NOT NULL,
    CONSTRAINT uq_group_word UNIQUE (group_id, word_id),
    CONSTRAINT fk_group_word_group FOREIGN KEY (group_id) REFERENCES friend_group (id),
    CONSTRAINT fk_group_word_word FOREIGN KEY (word_id) REFERENCES word (id),
    CONSTRAINT fk_group_word_user FOREIGN KEY (added_by) REFERENCES app_user (id)
);
CREATE INDEX idx_group_word_added ON group_word (group_id, added_at);
